<?php
declare(strict_types=1);

final class SupplierStatements
{
    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    private static function safe(mixed $value):int
    {
        $value=(string)$value;if(!preg_match('/^-?[0-9]+$/D',$value))throw new HttpError(409,'Số tiền trong sổ nguồn không hợp lệ.');$negative=str_starts_with($value,'-');$digits=ltrim($negative?substr($value,1):$value,'0') ?: '0';if(strlen($digits)>16||strlen($digits)===16&&strcmp($digits,'9007199254740991')>0)throw new HttpError(409,'Tổng tiền vượt phạm vi xử lý.');return $negative?-(int)$digits:(int)$digits;
    }
    private static function plus(int $a,int $b):int{$sum=$a+$b;if(abs($sum)>Pricing::MAX_SAFE)throw new HttpError(409,'Tổng tiền vượt phạm vi xử lý.');return $sum;}
    public function build(string $id,array $input,bool $export=false):array
    {
        if(!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$id)||array_diff(array_keys($input),['from','to','page'])||!is_string($input['from'] ?? null)||!is_string($input['to'] ?? null))throw new HttpError(400,'Chọn nhà cung cấp và khoảng ngày hợp lệ.');foreach(['from','to'] as $key)Pricing::validateDate($input[$key]);$page=$input['page'] ?? '1';if(!is_string($page)||!preg_match('/^[1-9][0-9]{0,5}$/D',$page)||(int)$page>100000)throw new HttpError(400,'Trang sao kê không hợp lệ.');$from=$input['from'];$to=$input['to'];$start=new DateTimeImmutable($from.'T00:00:00+07:00');$last=new DateTimeImmutable($to.'T00:00:00+07:00');if($from>$to||$last->getTimestamp()-$start->getTimestamp()>366*86400)throw new HttpError(400,'Khoảng sao kê tối đa 367 ngày.');$utc=new DateTimeZone('UTC');$begin=$start->setTimezone($utc)->format('Y-m-d H:i:s');$end=$last->modify('+1 day')->setTimezone($utc)->format('Y-m-d H:i:s');
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$this->db->beginTransaction();try{
            $raw=$this->query('SELECT data FROM jingo_suppliers WHERE id=?',[$id])->fetchColumn();if($raw===false)throw new HttpError(404,'Không tìm thấy nhà cung cấp.');$supplier=json_decode($raw,true,512,JSON_THROW_ON_ERROR);
            $opening=self::safe($this->query("SELECT CAST(COALESCE((SELECT SUM(CAST(unit_cost AS DECIMAL(50,0))*total_quantity) FROM jingo_supply_lots WHERE supplier_id=? AND unlimited=0 AND created_at<?),0)+COALESCE((SELECT SUM(CAST(unit_cost AS DECIMAL(50,0))*quantity) FROM jingo_supply_purchases WHERE supplier_id=? AND created_at<?),0)-COALESCE((SELECT SUM(CAST(amount AS DECIMAL(50,0))) FROM jingo_supplier_payments WHERE supplier_id=? AND created_at<?),0) AS CHAR)",[$id,$begin,$id,$begin,$id,$begin])->fetchColumn());
            $scopes=[['jingo_supply_lots',' AND unlimited=0'],['jingo_supply_purchases',''],['jingo_supplier_payments','']];$count=0;foreach($scopes as [$table,$where]){$count+=(int)$this->query("SELECT COUNT(*) FROM $table WHERE supplier_id=? AND created_at>=? AND created_at<?".$where,[$id,$begin,$end])->fetchColumn();if($count>10000)throw new HttpError(400,'Khoảng sao kê vượt 10.000 dòng. Chọn kỳ ngắn hơn; dữ liệu không bị cắt bớt.');}
            $rows=[];foreach($scopes as $index=>[$table,$where]){foreach($this->query("SELECT * FROM $table WHERE supplier_id=? AND created_at>=? AND created_at<?".$where.' ORDER BY created_at,id LIMIT 10001',[$id,$begin,$end])->fetchAll(PDO::FETCH_ASSOC) as $row){$kind=['PURCHASE','ON_DEMAND','PAYMENT'][$index];$data=$index===2?[]:json_decode($row['data'],true,512,JSON_THROW_ON_ERROR);$quantity=$index===2?null:self::safe($row[$index===0?'total_quantity':'quantity']);$unitCost=$index===2?null:self::safe($row['unit_cost']);if($quantity!==null&&($quantity<0||$unitCost<0||$quantity>0&&$unitCost>intdiv(Pricing::MAX_SAFE,$quantity)))throw new HttpError(409,'Giá trị dòng nguồn vượt phạm vi xử lý.');$increase=$index===2?0:$quantity*$unitCost;$decrease=$index===2?self::safe($row['amount']):0;if($decrease<0)throw new HttpError(409,'Khoản trả trong sổ nguồn không hợp lệ.');$rows[]=['id'=>$row['id'],'kind'=>$kind,'createdAt'=>str_replace(' ','T',$row['created_at']).'Z','reference'=>$index===0?$row['id']:($index===1?($data['orderCode'] ?? ''):$row['reference']),'description'=>$index===0?($data['note'] ?? ''):($index===1?'Lấy vé theo đơn · '.($data['note'] ?? ''):($row['method']==='CASH'?'Tiền mặt':'Chuyển khoản').' · '.$row['note']),'productName'=>$data['productName'] ?? '','variantName'=>$data['variantName'] ?? '','customerType'=>$row['customer_type'] ?? '','quantity'=>$quantity,'unitCost'=>$unitCost,'increase'=>$increase,'decrease'=>$decrease,'balance'=>0];}}
            $rank=['PURCHASE'=>0,'ON_DEMAND'=>1,'PAYMENT'=>2];usort($rows,fn($a,$b)=>strcmp($a['createdAt'],$b['createdAt'])?:($rank[$a['kind']]<=>$rank[$b['kind']])?:strcmp($a['id'],$b['id']));$balance=$opening;$purchased=0;$paid=0;foreach($rows as &$row){$purchased=self::plus($purchased,$row['increase']);$paid=self::plus($paid,$row['decrease']);$balance=self::plus($balance,$row['increase']-$row['decrease']);$row['balance']=$balance;}unset($row);$total=count($rows);$page=min((int)$page,max(1,(int)ceil($total/50)));$report=['supplier'=>['id'=>$id,'name'=>$supplier['name'],'status'=>$supplier['status']],'from'=>$from,'to'=>$to,'generatedAt'=>gmdate('Y-m-d\TH:i:s\Z'),'opening'=>$opening,'purchased'=>$purchased,'paid'=>$paid,'closing'=>$balance,'total'=>$total,'page'=>$page,'pageSize'=>50,'rows'=>$export?$rows:array_slice($rows,($page-1)*50,50)];$this->db->commit();return $report;
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public static function csvCell(mixed $value):string{$text=str_replace("\0",'',(string)($value ?? ''));if(preg_match('/^[\s\x{FEFF}]*[=+@-]|^[\t\r\n]/u',$text))$text="'".$text;return '"'.str_replace('"','""',$text).'"';}
    public static function csv(array $report):string
    {
        $prefix=[$report['supplier']['id'],$report['supplier']['name'],$report['from'],$report['to']];$rows=[['Mã NCC','Nhà cung cấp','Từ ngày','Đến ngày','Loại dòng','Ngày ghi nhận (GMT+7)','Mã ghi nhận','Tham chiếu','Sản phẩm','Gói','Nhóm khách','Số lượng','Giá mua (VND)','Tăng phải trả (VND)','Đã trả (VND)','Số dư (VND, không cộng cột này)','Nội dung'],array_merge($prefix,['Đầu kỳ',$report['from'],'','','','','','','','','',$report['opening'],''])];$groups=['ADULT'=>'Người lớn','CHILD'=>'Trẻ em','SENIOR'=>'Người cao tuổi','LOCAL_ADULT'=>'Người lớn · Địa phương','LOCAL_CHILD'=>'Trẻ em · Địa phương','LOCAL_SENIOR'=>'Người cao tuổi · Địa phương'];$zone=new DateTimeZone('Asia/Ho_Chi_Minh');foreach($report['rows'] as $row)$rows[]=array_merge($prefix,[['PURCHASE'=>'Nhập vé','ON_DEMAND'=>'Lấy vé theo đơn','PAYMENT'=>'Trả tiền NCC'][$row['kind']],(new DateTimeImmutable($row['createdAt']))->setTimezone($zone)->format('Y-m-d H:i:s'),$row['id'],$row['reference'],$row['productName'],$row['variantName'],$groups[$row['customerType']] ?? '',$row['quantity'] ?? '',$row['unitCost'] ?? '',$row['increase'],$row['decrease'],$row['balance'],$row['description']]);$rows[]=array_merge($prefix,['Cuối kỳ',$report['to'],'','','','','','','','','',$report['closing'],'']);return "\xEF\xBB\xBF".implode("\r\n",array_map(fn($row)=>implode(',',array_map([self::class,'csvCell'],$row)),$rows))."\r\n";
    }
}
